{
  "findings": [
    {
      "check_id": "CKV_GCP_124",
      "title": "Ensure GCP Cloud Function is not configured with overly permissive Ingress setting",
      "resource": "google_cloudfunctions_function.recovery_testing_service",
      "severity": "MEDIUM",
      "explanation": "The `ingress_settings` attribute is missing. By default, this may allow traffic from any source (ALLOW_ALL) depending on the provider version or project defaults, exposing the function to unnecessary network access."
    },
    {
      "check_id": "CKV2_GCP_10",
      "title": "Ensure GCP Cloud Function HTTP trigger is secured",
      "resource": "google_cloudfunctions_function.recovery_testing_service",
      "severity": "MEDIUM",
      "explanation": "While this function uses a Pub/Sub trigger rather than an HTTP trigger, the security best practice for Cloud Functions generally requires explicit ingress controls and authentication/authorization configurations. The lack of `ingress_settings` combined with potential default permissions makes it less secure. Note: CKV2_GCP_10 specifically targets HTTP triggers, but in the context of general hardening for functions without explicit ingress restrictions, applying `ingress_settings = "ALLOW_INTERNAL_ONLY"` or similar is the primary remediation available in the resource block itself."
    }
  ],
  "patched_code": "resource "google_cloudfunctions_function" "recovery_testing_service" {
  name        = "enterprise-disaster-recovery-orchestration-platform-function-testing"
  description = "Automated recovery testing service"
  runtime     = "python39"
  available_memory_mb   = 256
  source_archive_bucket = google_storage_bucket.primary_backup_storage.name
  source_archive_object = google_storage_bucket_object.testing_function_source.name
  trigger {
    event_type = "google.pubsub.topic.publish"
    resource   = google_pubsub_topic.recovery_testing_trigger.name
  }
  entry_point = "test_recovery"
  environment_variables = {
    DATABASE_HOST = google_sql_database_instance.recovery_database.ip_address.0.ip_address
    BACKUP_BUCKET = google_storage_bucket.primary_backup_storage.name
  }
  ingress_settings = "ALLOW_INTERNAL_ONLY"
  depends_on = [
    google_storage_bucket.primary_backup_storage,
    google_sql_database_instance.recovery_database
  ]
}",
  "fix_summary": "Added `ingress_settings = "ALLOW_INTERNAL_ONLY"` to restrict network access to internal sources only, mitigating the risk of overly permissive ingress settings as recommended by CKV_GCP_124."
}
